+    // LR_SHARED, LoadImageW returns an app-owned handle retained below.
+    let loaded = unsafe {
+        LoadImageW(
+            None,
+            PCWSTR(wide_path.as_ptr()),
+            IMAGE_ICON,
+            256,
+            256,
+            LR_LOADFROMFILE,
+        )
+    }
+    .map_err(|error| format!("failed loading taskbar icon: {error}"))?;
+    Ok((hwnd.0 as isize, OwnedWindowsIcon(Some(loaded.0 as isize))))
